        /// <param name="body"></param>
        /// <param name="id">VPS ID number</param>
        /// <returns>Task of QueueResponse</returns>
        System.Threading.Tasks.Task<QueueResponse> PostVpsReinstallOsAsync (TemplateRequest body, int? id);

